def poll(timeout: int = 0) -> list[dict]:
    """Return new button taps since last poll, acking the offset. timeout=0 -> non-blocking.
    HARD no-op in shared-bot mode so we never fight Nessobot's poller."""
    if shared() or not enabled():
        return []
    off = _load(OFFSET_PATH, {"offset": 0}).get("offset", 0)
    r = _call("getUpdates", {"offset": off, "timeout": timeout,
                             "allowed_updates": ["callback_query"]}, timeout=timeout + 15)
    out: list[dict] = []
    if not (r and r.get("ok")):
        return out
    max_id = off
    for u in r["result"]:
        max_id = max(max_id, u["update_id"] + 1)
        cq = u.get("callback_query")
        if not cq:
            continue
        msg = cq.get("message") or {}
        chat = msg.get("chat") or {}
        if str(chat.get("id", "")) != str(_chat()):
            continue
        out.append({"data": cq.get("data", ""), "query_id": cq.get("id"),
                    "message_id": msg.get("message_id"),
                    "chat_id": chat.get("id")})
    if max_id != off:
        _save(OFFSET_PATH, {"offset": max_id})
    return out

def _stocktwits(ticker: str, weight: float) -> list[RawSignal]:
    """Real-time per-ticker sentiment/buzz — adds a SOCIAL-family confirmation (long-biased)."""
    try:
        r = requests.get(f"https://api.stocktwits.com/api/2/streams/symbol/{ticker}.json",
                         headers={"User-Agent": UA}, timeout=10)
        if r.status_code != 200:
            return []
        msgs = r.json().get("messages", [])
        if len(msgs) < 3:
            return []
        def s(m):
            return ((m.get("entities") or {}).get("sentiment") or {}).get("basic")
        bull = sum(1 for m in msgs if s(m) == "Bullish")
        bear = sum(1 for m in msgs if s(m) == "Bearish")
        if bull <= bear:
