def _stocktwits(ticker: str, weight: float) -> list[RawSignal]:
    """Real-time per-ticker sentiment/buzz — adds a SOCIAL-family confirmation (long-biased)."""
    try:
        r = requests.get(f"https://api.stocktwits.com/api/2/streams/symbol/{ticker}.json",
                         headers={"User-Agent": UA}, timeout=10)
        msgs = r.json().get("messages", [])
        if len(msgs) < 3:
            return []
        def s(m):
            return ((m.get("entities") or {}).get("sentiment") or {}).get("basic")
        bull = sum(1 for m in msgs if s(m) == "Bullish")
        bear = sum(1 for m in msgs if s(m) == "Bearish")
        if bull <= bear:
            return []                                   # only confirm LONGs
        ratio = bull / max(1, bull + bear)
        return [RawSignal(source="stocktwits", weight=weight, ts=now_ts(), tickers=[ticker],
                          headline=f"{ticker} StockTwits {bull}B/{bear}Be ({ratio:.0%} bull, {len(msgs)} msgs)",
                          url="https://stocktwits.com", strength=min(2.0, 0.5 + ratio))]
    except Exception:
        return []

patch.find:
def _score_policy(weights, keep_frac, vecs, rets, folds=4):
    """Walk-forward objective with NO lookahead: for each time fold (test), learn the score cutoff from the
    OTHER folds (train) at the keep-fraction, apply out-of-sample, measure mean return of accepted. Returns
    overall mean return of accepted, or None if not robust (positive across a majority of folds) / too few
    accepted."""
    n = len(vecs)
    if n < 40:
        return None
    scores = [sum(w * v for w, v in zip(weights, vec)) for vec in vecs]
    size = n // folds
    fold_means, accepted_rets = [], []
    for k in range(folds):
        a, b = k * size, ((k + 1) * size if k < folds - 1 else n)
        cut = _percentile(sorted(scores[:a] + scores[b:]), 1.0 - keep_frac)
        acc = [rets[i] for i in range(a, b) if scores[i] >= cut]
        if acc:
            fold_means.append(sum(acc) / len(acc))
            accepted_rets += acc
    if len(accepted_rets) < max(20, int(0.03 * n)):
        return None
    if not fold_means or sum(1 for m in fold_means if m > 0) < (len(fold_means) + 1) // 2:
        return None
    return sum(accepted_rets) / len(accepted_rets)

