def _wilson_upper(wins: int, n: int, z: float = 1.64) -> float:
    if n == 0:
        return 1.0
    p = wins / n
    d = 1 + z * z / n
    c = p + z * z / (2 * n)
    m = z * math.sqrt((p * (1 - p) + z * z / (4 * n)) / n)
    return min(1.0, (c + m) / d)

